MATCH (e:PlantItem {tag: 'E-2903'})-[:line_to]-(v:Valve)<-[:control]-(a:PlantItem {kind: 'actuator'}), (loop:ProcessControlFunction)-[:send_signal_to*1..]->(a)
RETURN DISTINCT loop.loop_tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-601'}), (b:PlantItem {tag: 'P-602A'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem)
                    WHERE x.tag <> 'D-601' AND y.tag <> 'D-601')+ (b)
       } AS reachable_without_D601

MATCH (i:PlantItem {tag: 'V-3301'})-[:is_drawn_on]->(s:Sheet)
RETURN i.tag AS tag, s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'P-2601B'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (e:Equipment)-[:measured_by]->(i:PlantItem {loop_tag: 'TI-51020'})
RETURN DISTINCT e.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'EA-601'}), (b:PlantItem {tag: 'K-601'})
WHERE EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE y.tag <> 'D-601')+ (b)
}
RETURN a.tag AS from_tag, b.tag AS to_tag

MATCH (equipment:Equipment)-[:measured_by]->(sensor:PlantItem)-[:send_signal_to*0..]->(head:ProcessInstrumentationFunction {loop_tag: 'PI-49010'})
RETURN DISTINCT equipment.tag AS tag
ORDER BY tag;

MATCH (h:PlantItem:ElectricHeater {unit_id: '49'})
RETURN h.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'TK-2704'}), (b:PlantItem {tag: 'P-2701A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (:PlantItem {tag: 'P-1501B'})-[:measured_by]->(instrument:PlantItem)
RETURN DISTINCT instrument.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-3601B'}), (b:PlantItem {tag: 'V-3601'})
RETURN a.tag AS source_tag, b.tag AS target_tag,
       EXISTS { (a)-[:line_to*1..]->(b) } AS reachable;

MATCH (a:PlantItem {tag: 'E-1304'}), (b:PlantItem {tag: 'EJ-1302B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(v) AS valve_count

MATCH (:PlantItem {tag: 'T-1901'})-[:is_drawn_on]->(s:Sheet)
RETURN s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (a:PlantItem {tag: 'D-1301'}), (b:PlantItem {tag: 'T-1301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (item:PlantItem {tag: 'E-1502'})-[:is_drawn_on]->(sheet:Sheet)
RETURN DISTINCT sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem:TubularHeatExchanger {unit_id: '26'})
RETURN item.tag AS tag
ORDER BY tag;

MATCH (loop:ProcessControlFunction {loop_tag: 'LIC-17001'})-[:send_signal_to*1..]->(a:PlantItem {kind: 'actuator'})-[:control]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:PlantItem:AngleGlobeValve {unit_id: '44'})
RETURN v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'P-701C'}), (b:PlantItem {tag: 'P-701B'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'D-601'}), (b:PlantItem {tag: 'EA-601'}), (blocked:PlantItem {tag: 'P-601B'})
RETURN EXISTS {
  MATCH (a) ((n:PlantItem WHERE n <> blocked)-[:line_to]->){1,} (b)
} AS reachable

MATCH (a:PlantItem {tag: 'D-601'}), (b:PlantItem {tag: 'EA-601'}), (blocked:PlantItem {tag: 'P-601B'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> blocked AND y <> blocked){1,} (b)
} AS reachable

MATCH (a:PlantItem {tag: 'P-2801A'}), (b:PlantItem {tag: 'P-3001'})
WHERE EXISTS { (a)-[:line_to*1..]->(b) }
RETURN b.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'E-3001'}), (b:PlantItem {tag: 'V-3301'}), (v:PlantItem {tag: 'V-3001'})
RETURN EXISTS {
  MATCH (a) ((x:PlantItem)-[:line_to]->(y:PlantItem) WHERE x <> v AND y <> v)+ (b)
} AS reachable_without_V_3001

MATCH (a:PlantItem {tag: 'P-4001B'}), (b:PlantItem {tag: 'P-4402A'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'D-1901'}), (b:PlantItem {tag: 'TK-2704'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN count(DISTINCT v) AS valve_count

MATCH (a:PlantItem {tag: 'P-4101A'}), (b:PlantItem {tag: 'TK-5301'}), (blocked:PlantItem {tag: 'TK-4802'})
RETURN a.tag AS source_tag, b.tag AS destination_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x <> blocked AND y <> blocked)+ (b)
       } AS can_flow_without_blocked_tag

MATCH (a:PlantItem {tag: 'P-3601B'}), (b:PlantItem {tag: 'E-4903'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (a:PlantItem {tag: 'K-501'}), (b:PlantItem {tag: 'R-401'}), (h:PlantItem {tag: 'H-401'})
RETURN EXISTS {
  MATCH (a) ((x)-[:line_to]->(y) WHERE x <> h AND y <> h)+ (b)
} AS reachable

MATCH (a:PlantItem {tag: 'E-2903'}), (b:PlantItem {tag: 'TK-5301'}), (v:Valve)
WHERE EXISTS { (a)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(b) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (a:PlantItem {tag: 'K-501'}), (b:PlantItem {tag: 'R-401'}), (h:PlantItem {tag: 'H-401'})
RETURN a.tag AS from_tag, b.tag AS to_tag,
       EXISTS {
         MATCH (a) ((x)-[:line_to]->(y) WHERE x <> h AND y <> h)+ (b)
       } AS reachable

MATCH (:PlantItem:Valve {tag: 'YV-48002'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'LV-17001'})-[:line_to]->(fed:PlantItem)
RETURN DISTINCT fed.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'E-3001'})-[:line_to]->(item:PlantItem)
RETURN DISTINCT item.tag AS tag
ORDER BY tag;

MATCH (loop:PlantItem {loop_tag: 'FSLL-42004'})-[:send_signal_to*1..]->(actuator:PlantItem)-[:control]->(valve:Valve)
RETURN DISTINCT valve.tag AS tag
ORDER BY tag;

MATCH (i:PlantItem {tag: 'H-1101'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (item:PlantItem {tag: 'E-1502'})-[:is_drawn_on]->(sheet:Sheet)
RETURN item.tag AS tag, sheet.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (:PlantItem {tag: 'V-701'})-[:is_drawn_on]->(s:Sheet)
RETURN DISTINCT s.sheet_id AS sheet_id
ORDER BY sheet_id;

MATCH (p:PlantItem {tag: 'P-1902B'})-[:line_to*1..]->(v:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (:PlantItem {tag: 'F-901A'})-[:line_to*1..]->(v:PlantItem:Valve)
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-1802'}), (v:PlantItem:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (source:PlantItem {tag: 'P-701B'})
MATCH (source)-[:line_to*1..]->(v:Valve)
WHERE EXISTS {
  (v)-[:line_to*1..]->(equipment:Equipment)
}
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-2601A'}), (v:Valve)
WHERE EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-1902B'}), (v:PlantItem:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-701B'}), (v:PlantItem:Valve)
WHERE coalesce(v.operating_position, 'NO') = 'NO'
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (p:PlantItem {tag: 'P-2601A'}), (v:PlantItem:Valve)
WHERE v <> p
  AND (v.operating_position IS NULL OR v.operating_position = 'NO')
  AND NOT EXISTS { (:PlantItem)-[:control]->(v) }
  AND EXISTS { (p)-[:line_to*1..]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:GlobeValve:Valve {line_number: '4-P-260078-A1A-N'}), (y:PlantItem {tag: 'YV-27001'})
WHERE EXISTS { (v)-[:line_to*1..]->(y) }
RETURN v.tag AS tag, COALESCE(v.operating_position, 'NO') AS operating_position ORDER BY tag

MATCH (v:PlantItem:GlobeValve {line_number: '4-P-260061-A1A-N'})-[:line_to*1..]->(:PlantItem {tag: 'YV-27003'})
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS operating_position
ORDER BY tag, operating_position;

MATCH (v:PlantItem:ButterflyValve {line_number: '6-P-140002-A1A-N', kind: 'valve'}), (s:PlantItem {tag: 'STR-14002'})
WHERE EXISTS { (v)-[:line_to*1..]->(s) }
RETURN v.tag AS tag, coalesce(v.operating_position, 'NO') AS operating_position

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(p:PlantItem {tag: 'P-701A'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (p:PlantItem {tag: 'P-2601A'})-[:line_to*1..]->(v:PlantItem:Valve)
WHERE (v.operating_position IS NULL OR v.operating_position = 'NO')
  AND NOT EXISTS { (:PlantItem)-[:control]->(v) }
  AND EXISTS { (v)-[:line_to*1..]->(:PlantItem:Equipment) }
RETURN DISTINCT v.tag AS tag
ORDER BY tag

MATCH (v:PlantItem:Valve)-[:line_to*1..]->(d:PlantItem {tag: 'D-1801'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(d:PlantItem {tag: 'D-3701'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;

MATCH (v:Valve)-[:line_to*1..]->(e:PlantItem {tag: 'E-1502'})
RETURN DISTINCT v.tag AS tag
ORDER BY tag;
